// === Factory Method Pattern ===

// Product interface
public interface INotifier {
    Task SendAsync(string recipient, string message);
}

// Concrete products
public class EmailNotifier : INotifier {
    public async Task SendAsync(string recipient, string message) {
        await emailService.SendEmailAsync(recipient, message);
    }
}
public class SmsNotifier : INotifier {
    public async Task SendAsync(string recipient, string message) {
        await smsGateway.SendSmsAsync(recipient, message);
    }
}
public class PushNotifier : INotifier {
    public async Task SendAsync(string recipient, string message) {
        await pushService.SendPushAsync(recipient, message);
    }
}

// Creator with Factory Method
public abstract class NotificationSender {
    protected abstract INotifier CreateNotifier();  // Factory Method

    public async Task NotifyUserAsync(User user, string message) {
        var notifier = CreateNotifier();  // polymorphic creation
        await notifier.SendAsync(user.ContactInfo, message);
    }
}

// Concrete creators
public class EmailNotificationSender : NotificationSender {
    protected override INotifier CreateNotifier() => new EmailNotifier();
}
public class SmsNotificationSender : NotificationSender {
    protected override INotifier CreateNotifier() => new SmsNotifier();
}

// Simpler (modern): Factory via interface/delegate in DI
public interface INotifierFactory {
    INotifier Create(NotificationChannel channel);
}
public class NotifierFactory(IServiceProvider sp) : INotifierFactory {
    public INotifier Create(NotificationChannel channel) => channel switch {
        NotificationChannel.Email => sp.GetRequiredService<EmailNotifier>(),
        NotificationChannel.SMS   => sp.GetRequiredService<SmsNotifier>(),
        NotificationChannel.Push  => sp.GetRequiredService<PushNotifier>(),
        _ => throw new ArgumentException($"Unknown channel: {channel}")
    };
}
