// === Fluent Builder ===
public class QueryBuilder {
    private string _table = "";
    private readonly List<string> _columns = [];
    private string? _whereClause;
    private int? _limit;
    private string? _orderBy;

    public QueryBuilder From(string table) { _table = table; return this; }
    public QueryBuilder Select(params string[] columns) { _columns.AddRange(columns); return this; }
    public QueryBuilder Where(string clause) { _whereClause = clause; return this; }
    public QueryBuilder Limit(int n) { _limit = n; return this; }
    public QueryBuilder OrderBy(string column) { _orderBy = column; return this; }

    public string Build() {
        if (string.IsNullOrEmpty(_table)) throw new InvalidOperationException("Table required");
        var cols = _columns.Count > 0 ? string.Join(", ", _columns) : "*";
        var sql = $"SELECT {cols} FROM {_table}";
        if (_whereClause != null) sql += $" WHERE {_whereClause}";
        if (_orderBy != null) sql += $" ORDER BY {_orderBy}";
        if (_limit.HasValue) sql += $" LIMIT {_limit}";
        return sql;
    }
}

