public class PaymentProcessor {
    public decimal Process(string paymentType, decimal amount) {
        if (paymentType == "credit_card") {
            // credit card processing logic
            return amount * 0.98m;  // 2% fee
        } else if (paymentType == "paypal") {
            return amount * 0.97m;  // 3% fee
        } else if (paymentType == "crypto") {  // NEW: requires modifying existing class
            return amount * 0.99m;  // 1% fee
        }
        throw new ArgumentException($"Unknown payment type: {paymentType}");
    }
}
// Problem: every new payment method modifies this class → regression risk

// === OCP Applied ===
public interface IPaymentHandler {
    bool CanHandle(string paymentType);
    decimal Process(decimal amount);
}

public class CreditCardHandler : IPaymentHandler {
    public bool CanHandle(string type) => type == "credit_card";
    public decimal Process(decimal amount) => amount * 0.98m;
}

public class PayPalHandler : IPaymentHandler {
    public bool CanHandle(string type) => type == "paypal";
    public decimal Process(decimal amount) => amount * 0.97m;
}

// NEW payment method: add new class, no existing code modified
public class CryptoHandler : IPaymentHandler {
    public bool CanHandle(string type) => type == "crypto";
    public decimal Process(decimal amount) => amount * 0.99m;
}

// PaymentProcessor: closed for modification, open for extension
public class PaymentProcessor(IEnumerable<IPaymentHandler> handlers) {
    public decimal Process(string paymentType, decimal amount) {
        var handler = handlers.FirstOrDefault(h => h.CanHandle(paymentType))
            ?? throw new ArgumentException($"No handler for {paymentType}");
        return handler.Process(amount);
    }
}

// DI registration:
builder.Services.AddScoped<IPaymentHandler, CreditCardHandler>();
builder.Services.AddScoped<IPaymentHandler, PayPalHandler>();
builder.Services.AddScoped<IPaymentHandler, CryptoHandler>();  // new: no other changes
