// === LSP Violation: Square/Rectangle problem ===
public class Rectangle {
    public virtual int Width { get; set; }
    public virtual int Height { get; set; }
    public int Area() => Width * Height;
}

public class Square : Rectangle {
    public override int Width {
        set { base.Width = value; base.Height = value; }  // enforces equal sides
    }
    public override int Height {
        set { base.Width = value; base.Height = value; }
    }
}

void TestRectangle(Rectangle r) {
    r.Width = 5;
    r.Height = 3;
    Console.WriteLine(r.Area());  // Expected: 15, for Square: 9 → LSP violated
}

// === LSP Applied: separate abstractions ===
public interface IShape { int Area(); }
public class Rectangle(int width, int height) : IShape {
    public int Area() => width * height;
}
public class Square(int side) : IShape {
    public int Area() => side * side;
}
// Now: Square doesn't inherit from Rectangle, both implement IShape correctly

// === LSP with contracts ===
public abstract class FileStorage {
    // Contract: returns content or throws FileNotFoundException — never null
    public abstract byte[] ReadFile(string path);

    // Postcondition: returned array length > 0
    // Precondition: path must not be null or empty
}

public class LocalFileStorage : FileStorage {
    public override byte[] ReadFile(string path) {
        if (string.IsNullOrEmpty(path)) throw new ArgumentNullException(nameof(path));
        return File.ReadAllBytes(path);  // honours contract: throws FileNotFoundException if not found
    }
}

public class S3FileStorage : FileStorage {
    public override byte[] ReadFile(string path) {
        // MUST honour same contract: throw if not found, never return null
        var content = _s3Client.GetObjectBytes(path);
        return content ?? throw new FileNotFoundException(path);  // honour postcondition
    }
}
