// === ISP Violation: fat IRepository interface ===
public interface IRepository<T> {
    T GetById(int id);
    IEnumerable<T> GetAll();
    void Add(T entity);
    void Update(T entity);
    void Delete(int id);
    // Also: report-specific methods
    IEnumerable<T> Search(string query);
    IEnumerable<T> GetByDateRange(DateTime from, DateTime to);
    byte[] ExportToCsv();
    Task<PaginatedResult<T>> GetPaged(int page, int size);
}
// A ReadOnlyReportRepository must implement Add, Update, Delete
// — throwing NotImplementedException: LSP violation

// === ISP Applied: segregated interfaces ===
// Read operations
public interface IReadRepository<T> {
    T? GetById(int id);
    IEnumerable<T> GetAll();
}

// Write operations
public interface IWriteRepository<T> {
    void Add(T entity);
    void Update(T entity);
    void Delete(int id);
}

// Search capability (optional)
public interface ISearchableRepository<T> {
    IEnumerable<T> Search(string query);
    IEnumerable<T> GetByDateRange(DateTime from, DateTime to);
}

// Report-specific
public interface IExportableRepository<T> {
    byte[] ExportToCsv();
    Task<PaginatedResult<T>> GetPaged(int page, int size);
}

// Full implementation: implements all relevant interfaces
public class OrderRepository
    : IReadRepository<Order>,
      IWriteRepository<Order>,
      ISearchableRepository<Order>,
      IExportableRepository<Order> {
    // implements all methods meaningfully
}

// Read-only report service: only depends on what it needs
public class OrderReportService(
    IReadRepository<Order> orders,          // can read
    IExportableRepository<Order> exporter)  // can export
{
    public async Task<byte[]> GenerateReportAsync() {
        var allOrders = orders.GetAll();
        return exporter.ExportToCsv();
    }
