    [Fact]
    public async Task GetPrice_SameCurrency_ReturnsDirectly() {
        // Arrange
        _products.Setup(p => p.GetByIdAsync(1))
            .ReturnsAsync(new Product { Id = 1, Price = 29.99m, Currency = "USD" });

        // Act
