# Schema definition (SDL)
type Order {
  id: ID!
  status: String!
  total: Float!
  customer: Customer!     # nested type
  items: [OrderItem!]!   # list of non-null items
  createdAt: DateTime!
}

type Query {
  order(id: ID!): Order     # nullable — returns null if not found
  orders(status: String, first: Int, after: String): OrderConnection!
}

