# Token Bucket implementation (Redis-backed for distributed systems)
import redis
import time

class TokenBucket:
    def __init__(self, redis_client, key: str, rate: float, capacity: int):
        self.r = redis_client
        self.key = key
        self.rate = rate        # tokens added per second
        self.capacity = capacity  # max burst size

    def allow_request(self) -> bool:
        """Returns True if request allowed, False if rate limited."""
        now = time.time()
        with self.r.pipeline() as pipe:
            try:
                pipe.watch(self.key)
                data = self.r.hgetall(self.key)
                tokens = float(data.get(b'tokens', self.capacity))
                last_refill = float(data.get(b'last_refill', now))

                # Refill tokens based on elapsed time
                elapsed = now - last_refill
                tokens = min(self.capacity, tokens + elapsed * self.rate)

                if tokens < 1:
                    return False  # Rate limited

                tokens -= 1  # Consume one token

                pipe.multi()
                pipe.hset(self.key, mapping={
                    'tokens': tokens,
                    'last_refill': now
                })
                pipe.expire(self.key, 3600)
                pipe.execute()
                return True
            except redis.WatchError:
                return self.allow_request()  # Retry on concurrent modification

# Rate limit strategies:
algorithm_tradeoffs = {
    'fixed_window': {
        'memory': 'O(1)',
        'con': 'burst at window boundary — 2x rate for 1 second'
    },
    'sliding_log': {
        'memory': 'O(n) per user — stores all timestamps',
        'pro': 'perfectly accurate',
        'con': 'memory intensive at scale'
    },
    'token_bucket': {
        'memory': 'O(1)',
        'pro': 'allows bursts up to capacity, averages to rate',
        'use': 'APIs allowing burst traffic (downloads, batch)
    },
    'leaky_bucket': {
        'memory': 'O(n) — queue of pending requests',
        'pro': 'perfectly smooth output rate',
        'use': 'traffic shaping for downstream services'
    }
}
