// MassTransit saga state machine (orchestration)
public class OrderStateMachine : MassTransitStateMachine<OrderSagaState> {
    public State AwaitingInventory { get; private set; } = null!;
    public State AwaitingPayment { get; private set; } = null!;

    public Event<OrderCreated> OrderCreated { get; private set; } = null!;
    public Event<StockReserved> StockReserved { get; private set; } = null!;
    public Event<PaymentFailed> PaymentFailed { get; private set; } = null!;

    public OrderStateMachine() {
        Initially(When(OrderCreated)
            .Then(ctx => ctx.Saga.OrderId = ctx.Message.OrderId)
            .PublishAsync(ctx => ctx.Init<ReserveStock>(new { ctx.Message.OrderId }))
            .TransitionTo(AwaitingInventory));

        During(AwaitingInventory,
            When(StockReserved)
                .PublishAsync(ctx => ctx.Init<ChargePayment>(new { ctx.Saga.OrderId }))
                .TransitionTo(AwaitingPayment));

        During(AwaitingPayment,
            When(PaymentFailed)
                .PublishAsync(ctx => ctx.Init<ReleaseStock>(new { ctx.Saga.OrderId }))  // compensate
                .TransitionTo(Cancelled));
    }
}
