// .NET: IAsyncEnumerable provides implicit back-pressure
// The consumer controls the pace; producer doesn't advance until consumer requests next item

public async IAsyncEnumerable<SensorReading> StreamReadingsAsync(
    [EnumeratorCancellation] CancellationToken ct = default) {
    while (!ct.IsCancellationRequested) {
        var reading = await _sensor.ReadNextAsync(ct);  // waits for consumer to pull
        yield return reading;  // producer can't advance until consumer does 'await foreach { }' iteration
    }
}

// Consumer controls pace:
await foreach (var reading in StreamReadingsAsync(cancellationToken)) {
    await ProcessReadingAsync(reading);  // slow processing here
    // producer only sends next reading AFTER this await completes
}
// IAsyncEnumerable is pull-based — consumer drives pace

// Kafka back-pressure:
// Kafka consumer group with max.poll.records = 100
// Consumer calls poll() → gets ≤100 records → processes → poll() again
// Processing speed determines poll() frequency → natural back-pressure
// If consumer falls behind: consumer lag increases (Kafka retains messages)
// Monitor: kafka_consumer_lag > threshold → alert, add consumer instances

// System.Threading.Channels — bounded channel with back-pressure
var channel = Channel.CreateBounded<SensorReading>(new BoundedChannelOptions(1000) {
    FullMode = BoundedChannelFullMode.Wait  // producer blocks when channel is full
});

// Producer:
await channel.Writer.WriteAsync(reading, ct);  // blocks if channel is full

// Consumer:
await foreach (var reading in channel.Reader.ReadAllAsync(ct)) {
    await ProcessReadingAsync(reading);  // controls pace via WriteAsync blocking
}
