        var total = cmd.Items.Sum(i => i.Price * i.Quantity);
        var order = new Order {
            Id = Guid.NewGuid().ToString(),
            CustomerId = cmd.CustomerId,
            Total = total,
            Status = "pending"
        };
        _db.Orders.Add(order);
        await _db.SaveChangesAsync(ct);
        await _bus.Publish(new OrderPlacedEvent(order.Id, total), ct);
        return new PlaceOrderResult(order.Id, total);
    }
}

