from hypothesis.stateful import RuleBasedStateMachine, rule, invariant

class ShoppingCartMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.cart = ShoppingCart()
        self.expected_item_count = 0

    @rule(item=st.text(min_size=1), qty=st.integers(1, 10))
    def add_item(self, item, qty):
        self.cart.add(item, qty)
        self.expected_item_count += qty

    @rule()
    def clear_cart(self):
        self.cart.clear()
        self.expected_item_count = 0

    @invariant()
    def cart_count_matches(self):
        assert self.cart.total_items() == self.expected_item_count

