```csharp
// Polly v8 with Microsoft.Extensions.Resilience:
using Polly;
using Polly.CircuitBreaker;
using Polly.Bulkhead;
using Polly.RateLimit;

// Register in Program.cs:
builder.Services.AddHttpClient<IInventoryClient, InventoryClient>()
    .AddResilienceHandler("inventory-pipeline", pipeline => {
        // 1. Retry (inner — retries before circuit breaker sees it):
        pipeline.AddRetry(new HttpRetryStrategyOptions {
            MaxRetryAttempts = 3,
            Delay = TimeSpan.FromMilliseconds(200),
            UseJitter = true,  // avoid thundering herd on recovery
            ShouldHandle = args => args.Outcome switch {
                { Exception: HttpRequestException } => PredicateResult.True(),
                { Result.StatusCode: HttpStatusCode.ServiceUnavailable } => PredicateResult.True(),
                _ => PredicateResult.False()
            }
        });

        // 2. Circuit Breaker (wraps retry — opens after repeated failures):
        pipeline.AddCircuitBreaker(new HttpCircuitBreakerStrategyOptions {
            FailureRatio = 0.5,          // open when 50% of requests fail
            SamplingDuration = TimeSpan.FromSeconds(30),
            MinimumThroughput = 10,      // need at least 10 requests to evaluate
            BreakDuration = TimeSpan.FromSeconds(30),  // stay open for 30s
            OnOpened = args => {
                _logger.LogWarning('Circuit breaker opened for inventory service');
                _metrics.Increment('circuit_breaker.opened', new[] {"service:inventory"});
                return ValueTask.CompletedTask;
            }
        });

        // 3. Bulkhead (outermost — limits concurrent calls):
        pipeline.AddConcurrencyLimiter(new ConcurrencyLimiterOptions {
            PermitLimit = 10,        // max 10 concurrent inventory calls
            QueueLimit = 5           // queue up to 5 additional calls
        });
    });

// Rate limiting (backpressure on incoming requests):
builder.Services.AddRateLimiter(options => {
    options.AddFixedWindowLimiter('api', policy => {
        policy.PermitLimit = 1000;  // 1000 requests per window
        policy.Window = TimeSpan.FromSeconds(1);
        policy.QueueLimit = 100;    // queue 100, reject beyond that with 429
        policy.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
    });
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
});
// Apply: app.UseRateLimiter(); and [EnableRateLimiting("api")] on controllers
