// Cloudflare Worker — edge authentication + personalisation:
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 1. Rate limiting at the edge (no origin request needed):
    const ip = request.headers.get('CF-Connecting-IP');
    const key = `rate:${ip}`;
    const requests = await env.KV.get(key, { type: 'json' }) || { count: 0 };
    if (requests.count > 100) {
      return new Response('Rate limit exceeded', { status: 429 });
    }
    ctx.waitUntil(env.KV.put(key, JSON.stringify({ count: requests.count + 1 }), {
      expirationTtl: 60  // reset every minute
    }));

    // 2. JWT verification at edge (no origin round-trip):
    const authHeader = request.headers.get('Authorization');
    if (authHeader) {
      const token = authHeader.split(' ')[1];
      // verify JWT using SubtleCrypto (ECDSA/RSA — built into Workers runtime)
      const valid = await verifyJwt(token, env.JWT_PUBLIC_KEY);
      if (!valid) return new Response('Unauthorized', { status: 401 });
    }

    // 3. Geo-routing:
    const country = request.cf?.country;
    if (country === 'DE' || country === 'FR') {
      url.hostname = 'eu.origin.example.com';  // EU data residency
    }

    // 4. Forward to origin with modified request:
    return fetch(new Request(url, request));
  }
};
