```sql
-- Citus (PostgreSQL extension) setup:
-- Add worker nodes to the coordinator:
SELECT master_add_node('worker1', 5432);
SELECT master_add_node('worker2', 5432);
SELECT master_add_node('worker3', 5432);

-- Distribute the orders table by customer_id (shard key):
SELECT create_distributed_table('orders', 'customer_id');
-- Citus creates 32 shards across workers (configurable)
-- All rows with customer_id X go to the same shard

-- Distribute related table (colocated with orders):
SELECT create_distributed_table('order_items', 'customer_id', colocate_with => 'orders');
-- order_items with customer_id X → same shard as orders with customer_id X
-- JOIN between orders and order_items is local (no cross-shard query)!

-- Query: customer's orders (all on one shard → fast):
SELECT * FROM orders WHERE customer_id = 12345;
-- Citus routes directly to the shard holding customer 12345

-- Query: total revenue (cross-shard → coordinator aggregates):
SELECT SUM(total) FROM orders WHERE created_at > '2025-01-01';
-- Citus sends parallel query to all 32 shards → aggregates results on coordinator
```

